void no_ready(){const auto s=snapshot();require(!s.ready&&!s.stopping&&!s.failed&&s.worker_alive,"dirty recovery remains live and unready");auto d=sentinel<PrDiscoveryV1>();const auto before=bytes(d);const auto c=pr_executor_discovery_v1(slot.owner,&d);require((c==PR_EXECUTOR_EMPTY||c==PR_EXECUTOR_BUSY)&&bytes(d)==before,"dirty discovery cannot expose stale candidate");}
