uint64_t start(Mode mode=Mode::ORDINARY,uint64_t startup=0,uint32_t prefix_count=3){require(!slot.owner&&slot.epoll==-1,"previous executor closed");probe.reset(mode);probe.prefix_count=prefix_count;auto f=table();auto o=options();auto* input=pack(prefix_count);if(!startup)startup=until();require(pr_executor_create_v2(&f,&o,1,&input,startup,&slot.owner)==PR_EXECUTOR_OK&&!input&&slot.owner,"actual ABI2 consumes owned captured prefix");f.apply_device_change=poison_apply;o.owner_id=999;slot.watches();probe.wait(BOOTSTRAP_ENTER);const auto r=state();base_state(r);require(r.invalidation_epoch==0&&r.admitted_epoch==0&&r.applied_epoch==0&&r.accepted_epoch==0&&r.last_admitted_sequence==prefix_count&&r.last_applied_sequence==0&&r.discovery_sequence==0&&r.reconcile_not_after_boottime_ns==startup,"held bootstrap genuine initial functional state");return startup;}
