PrSessionRenderEventV1 change(uint64_t sequence){PrSessionRenderEventV1 e{};e.version=1;e.event_type=5;e.session_sequence=sequence;e.session_generation=SESSION;e.device_lease_id=LEASE;e.device_generation=3;e.rdev=device_rdev;e.active=1;e.change_type=static_cast<uint32_t>(sequence%2);e.connector_id=1;e.prop_id=static_cast<uint32_t>(sequence+100);e.boot_vga=1;std::memset(e.seat_name,0xAB,sizeof(e.seat_name));std::memset(e.device_path,0xCD,sizeof(e.device_path));std::memcpy(e.seat_name,"seat-ffi",9);std::memcpy(e.device_path,"/dev/null",10);e.seat_name[63]=0;e.device_path[255]=0;return e;}
