void caught_up(uint64_t epoch,uint64_t sequence){ready(sequence);const auto r=state();base_state(r);require(r.invalidation_epoch==epoch&&r.admitted_epoch==epoch&&r.applied_epoch==epoch&&r.accepted_epoch==epoch&&r.last_admitted_sequence==sequence&&r.last_applied_sequence==sequence&&r.discovery_sequence==sequence,"latest applied/accepted watermarks actually catch up");}
void refusal(const PrSessionRenderEventV1& event,int32_t expected){const auto before=state();auto input=event;const auto original=bytes(input);require(pr_executor_try_session_change_v2(slot.owner,&input)==expected&&bytes(input)==original,"ordinary refused CHANGE preserves caller bytes");require(bytes(state())==bytes(before),"ordinary refused CHANGE preserves all10watermarks");}
void retained_release(){const bool watched=slot.registered;slot.unwatch();auto* original=slot.owner;require(pr_executor_try_release(&slot.owner)==PR_EXECUTOR_BUSY&&slot.owner==original,"Busy release retains exact live owner slot");if(watched)slot.watches();}
void close_owner(){require(pr_executor_stop(slot.owner)==PR_EXECUTOR_OK,"actual terminal Stop");probe.wait(SHUTDOWN_PENDING);require(pr_executor_try_join(slot.owner)==PR_EXECUTOR_BUSY,"actual authored pending shutdown keeps join Busy");retained_release();probe.open(&Probe::shutdown_open);probe.signal();const auto cutoff=std::min(close_until,now()+2*SECOND);for(;;){const auto c=pr_executor_try_join(slot.owner);if(c==PR_EXECUTOR_OK)break;require(c==PR_EXECUTOR_BUSY&&now()<cutoff,"actual original bounded join");std::this_thread::yield();}const auto s=snapshot();require(s.joined&& !s.worker_alive,"actual joined worker snapshot");size_t n=0;const auto records=probe.copy(n);pid_t worker=0;bool dead=false;for(size_t i=0;i<n;++i){if(records[i].event==CREATE)worker=records[i].thread;if(records[i].event==DESTROY)dead=true;}require(worker>0&&worker!=control_tid&&dead,"worker create/destroy identity");for(size_t i=0;i<n;++i)require(records[i].thread==worker,"all callbacks on exact same actual worker");char task[128];std::snprintf(task,sizeof(task),"/proc/self/task/%d",worker);uint64_t absent=0;while(now()<cutoff){const auto status=access(task,F_OK);const auto code=errno;const auto t=now();if(status<0&&code==ENOENT){require(t<cutoff,"actual worker task absence cutoff");absent=t;break;}require(status==0,"worker task observation");std::this_thread::yield();}require(absent!=0,"actual joined worker task disappeared");slot.unwatch();require(pr_executor_try_release(&slot.owner)==PR_EXECUTOR_OK&&!slot.owner,"release after actual join");require(close(slot.epoll)==0,"owned epoll closed");slot.epoll=-1;size_t enter_count=0,return_count=0;for(size_t i=0;i<n;++i){if(records[i].event==APPLY_ENTER){require(enter_count==return_count&&records[i].sequence==4+enter_count,"apply callback exact order without overlap/retry");++enter_count;}if(records[i].event==APPLY_RETURN){require(enter_count==return_count+1&&records[i].sequence==4+return_count,"apply return exact sequence");++return_count;}}require(enter_count==probe.apply_count&&return_count==probe.apply_count,"everyactualapply entered and returned exactly once");for(size_t i=0;i<probe.apply_count;++i){require(bytes(probe.copied[i])==bytes(probe.expected[i]),"all408bytes retained after actual apply");std::printf("SESSION_RECONCILE_APPLY worker_tid=%d ordinal=%zu sequence=%llu copied408_equal=true\n",worker,i+1,static_cast<unsigned long long>(probe.copied[i].session_sequence));}std::printf("SESSION_RECONCILE_OBSERVATION worker_tid=%d control_tid=%d callbacks=%zu applies=%zu actual_join=true task_absent_at_ns=%llu\n",worker,control_tid,n,probe.apply_count,static_cast<unsigned long long>(absent));}
void pass(const char* name){require(now()<work_until,"original global5s work cutoff");std::printf("SESSION_RECONCILE_PASS %s\n",name);std::fflush(stdout);}
void wrong_threads(){auto out=sentinel<PrSessionReconciliationV2>();const auto before=bytes(out);auto e=change(4);const auto eb=bytes(e);const auto original=state();std::exception_ptr failure;std::mutex mutex;std::condition_variable changed;bool done=false;pid_t foreign_tid=0;std::thread foreign([&]{try{foreign_tid=tid();require(foreign_tid!=control_tid,"actual foreign thread");require(pr_executor_reconciliation_v2(slot.owner,&out)==PR_EXECUTOR_INVALID&&bytes(out)==before,"wrong-thread read preserves80bytes");require(pr_executor_invalidate_session_v2(slot.owner,SESSION)==PR_EXECUTOR_INVALID,"wrong-thread invalidation refuses");require(pr_executor_try_session_change_v2(slot.owner,&e)==PR_EXECUTOR_INVALID&&bytes(e)==eb,"wrong-thread event preserves bytes");}catch(...){failure=std::current_exception();}{std::lock_guard lock(mutex);done=true;changed.notify_all();}});const auto cutoff=until();{std::unique_lock lock(mutex);while(!done){const auto t=now();if(t>=cutoff){std::fputs("SESSION_RECONCILE_FAIL retained_foreign_thread_process_exit\n",stderr);std::fflush(stderr);std::_Exit(1);}changed.wait_for(lock,std::chrono::nanoseconds(cutoff-t));}}foreign.join();if(failure)std::rethrow_exception(failure);require(bytes(state())==bytes(original),"wrong-thread attempts preserve functional state");std::printf("SESSION_RECONCILE_OBSERVATION foreign_tid=%d control_tid=%d actual_join=true wrong_thread_refusals=3\n",foreign_tid,control_tid);}
void full_capacity_subtest(){start();for(uint64_t i=0;i<32;++i){invalidate();enqueue(4+i);}invalidate();const auto full=state();require(full.invalidation_epoch==33&&full.admitted_epoch==32&&full.applied_epoch==0&&full.accepted_epoch==0&&full.last_admitted_sequence==35&&full.last_applied_sequence==0&&full.discovery_sequence==0,"genuine heldbootstrap queue full32 plus unmatchedinvalidate");refusal(change(36),PR_EXECUTOR_CAPACITY);require(bytes(state())==bytes(full),"CAPACITY preserves all10watermarks and original pending33");require(pr_executor_stop(slot.owner)==PR_EXECUTOR_OK,"actual Stop while fullqueue bootstrap held");require(pr_executor_try_join(slot.owner)==PR_EXECUTOR_BUSY,"fullqueue heldbootstrap retains actual worker");retained_release();probe.open(&Probe::bootstrap_open);probe.wait(BOOTSTRAP_RETURN);probe.wait(SHUTDOWN_PENDING);auto d=sentinel<PrDiscoveryV1>();const auto db=bytes(d);require(pr_executor_discovery_v1(slot.owner,&d)==PR_EXECUTOR_EMPTY&&bytes(d)==db&&!snapshot().ready,"fullqueue Stop cannot publishlatebootstrapReady");close_owner();require(probe.apply_count==0,"terminalStop must not retry queued native applies");}
void abi_and_refusals(){probe.reset();auto* input=pack();auto* original=input;PrExecutor* output=nullptr;auto good=table();auto opts=options();for(unsigned which=0;which<4;++which){auto bad=good;if(which==0)bad.abi_version=1;if(which==1)bad.struct_size=112;if(which==2)bad.apply_device_change=nullptr;if(which==3)bad.reserved[0]=1;require(pr_executor_create_v2(&bad,&opts,1,&input,until(),&output)==PR_EXECUTOR_INVALID&&input==original&&!output,"ABI2 validation before bootstrap/owner consumption");}pr_bootstrap_release(input);start(Mode::ORDINARY,0,4);initial_ready();require(state().bootstrap_end_sequence==4&&state().last_admitted_sequence==4&&state().last_applied_sequence==4&&state().discovery_sequence==4,"genuine4event prefix is not hardcoded3");close_owner();start();wrong_threads();auto before=state();require(pr_executor_invalidate_session_v2(slot.owner,SESSION+1)==PR_EXECUTOR_INVALID&&bytes(state())==bytes(before),"wrong-session invalidate preserves state");auto scratch=sentinel<PrSessionReconciliationV2>();const auto sb=bytes(scratch);require(pr_executor_reconciliation_v2(nullptr,&scratch)==PR_EXECUTOR_INVALID&&bytes(scratch)==sb,"null owner read preserves output");require(pr_executor_reconciliation_v2(slot.owner,nullptr)==PR_EXECUTOR_INVALID&&bytes(state())==bytes(before),"null output read preserves state");invalidate();auto e=change(4);for(unsigned i=0;i<12;++i){auto bad=e;if(i==0)bad.version=2;if(i==1)bad.event_type=6;if(i==2)bad.session_generation=SESSION+1;if(i==3)bad.device_lease_id=LEASE+1;if(i==4)bad.device_generation=4;if(i==5)bad.rdev^=1;if(i==6)bad.reserved[0]=1;if(i==7)bad.change_type=2;if(i==8)std::memset(bad.seat_name,'X',sizeof(bad.seat_name));if(i==9)std::memset(bad.device_path,'X',sizeof(bad.device_path));if(i==10)bad.active=2;if(i==11)bad.boot_vga=2;refusal(bad,PR_EXECUTOR_INVALID);}refusal(change(5),PR_EXECUTOR_STALE);enqueue(4);invalidate();refusal(change(4),PR_EXECUTOR_STALE);refusal(change(6),PR_EXECUTOR_STALE);enqueue(5);probe.open(&Probe::bootstrap_open);probe.wait(APPLY_ENTER,4);probe.open_apply(0);probe.wait(APPLY_ENTER,5);probe.open_apply(1);caught_up(2,5);refusal(change(6),PR_EXECUTOR_BUSY);close_owner();full_capacity_subtest();pass("ABI2_required_apply_and_atomic_refusals");}
void held_bootstrap_latest(){const auto deadline=start();invalidate();enqueue(4);invalidate();enqueue(5);invalidate();enqueue(6);auto r=state();require(r.invalidation_epoch==3&&r.admitted_epoch==3&&r.applied_epoch==0&&r.accepted_epoch==0&&r.last_admitted_sequence==6&&r.last_applied_sequence==0&&r.discovery_sequence==0&&r.reconcile_not_after_boottime_ns==deadline,"three prebootstrap changes preserve original deadline");probe.open(&Probe::bootstrap_open);probe.wait(APPLY_ENTER,4);no_ready();r=state();require(r.applied_epoch==0&&r.accepted_epoch==0&&r.last_applied_sequence==3&&r.discovery_sequence==3,"held first apply cannot claim applied");probe.open_apply(0);probe.wait(APPLY_ENTER,5);no_ready();r=state();require(r.invalidation_epoch==3&&r.admitted_epoch==3&&r.applied_epoch==1&&r.accepted_epoch==0&&r.last_applied_sequence==4&&r.discovery_sequence==4&&r.reconcile_not_after_boottime_ns==deadline,"stale first refresh remains unaccepted");probe.open_apply(1);/* No control Rust call, queue admission or extra eventfd signal before third entry. */probe.wait(APPLY_ENTER,6);no_ready();r=state();require(r.invalidation_epoch==3&&r.admitted_epoch==3&&r.applied_epoch==2&&r.accepted_epoch==0&&r.last_applied_sequence==5&&r.discovery_sequence==5&&r.reconcile_not_after_boottime_ns==deadline,"thirdqueued apply drains without extra controlwake; secondcandidate staysstale");probe.open_apply(2);caught_up(3,6);require(state().reconcile_not_after_boottime_ns==deadline,"initial reconciliation never renews deadline");{std::lock_guard lock(probe.mutex);require(probe.apply_count==3&&bytes(probe.copied[0])==bytes(probe.expected[0])&&bytes(probe.copied[1])==bytes(probe.expected[1])&&bytes(probe.copied[2])==bytes(probe.expected[2]),"three exact ordered immutable408byte applies");}close_owner();pass("held_bootstrap_three_copied_changes_latest_only_Ready");}
void post_ready_fixed_burst(){start();initial_ready();const auto before=now();invalidate();const auto after=now();auto r=state();const auto deadline=r.reconcile_not_after_boottime_ns;require(deadline>=before+20*SECOND&&deadline<=after+20*SECOND,"Rust realBOOTTIME firstburst nowplus20s");kernel_deadline(deadline,true);enqueue(4);probe.wait(APPLY_ENTER,4);invalidate();require(state().reconcile_not_after_boottime_ns==deadline,"second invalidate cannot extend active burst");kernel_deadline(deadline,true);refusal(change(6),PR_EXECUTOR_STALE);require(state().reconcile_not_after_boottime_ns==deadline,"stale refusal cannot extend active burst");kernel_deadline(deadline,true);enqueue(5);probe.open_apply(0);probe.wait(APPLY_ENTER,5);no_ready();r=state();require(r.accepted_epoch==0&&r.applied_epoch==1&&r.reconcile_not_after_boottime_ns==deadline,"late first refresh cannot renew or becomeReady");probe.open_apply(1);caught_up(2,5);require(state().reconcile_not_after_boottime_ns==deadline,"clean retains last burstdeadline");kernel_deadline(deadline,false);close_owner();pass("postReady_real_fixed20s_burst_no_renewal");}
PrAdmissionV1 submit(uint64_t scene){auto* f=frame(A,scene);auto policy_value=policy(A,scene);PrAdmissionV1 a{};require(pr_executor_try_submit_v1(slot.owner,&f,&policy_value,work_until,scene+900,&a)==PR_EXECUTOR_OK&&!f&&a.id>0,"actual immutable Frame admission transfer");return a;}
void refuse_dirty_frame(){auto* f=frame(A,99);auto* original=f;auto out=sentinel<PrAdmissionV1>();const auto before=bytes(out);auto p=policy(A,99);require(pr_executor_try_submit_v1(slot.owner,&f,&p,work_until,999,&out)==PR_EXECUTOR_BUSY&&f==original&&bytes(out)==before,"dirty admission retains exact Frame/output");frame_value(f,99);pr_frame_release(f);}
void drain(const PrAdmissionV1& a,bool sealed){const auto cutoff=until();bool retired=false;unsigned outcome=0,attempt=0;while(!retired){PrCompletionV1 c{};const auto status=pr_executor_next_completion_v1(slot.owner,&c);if(status==PR_EXECUTOR_EMPTY||status==PR_EXECUTOR_BUSY){slot.wait(cutoff);continue;}require(status==PR_EXECUTOR_OK&&c.admission.id==a.id&&c.admission.control_cookie==a.control_cookie&&bytes(c.admission.policy)==bytes(a.policy),"actual correlated completion");if(c.kind==PR_COMPLETION_ATTEMPT)++attempt;if(c.kind==PR_COMPLETION_OUTCOME)++outcome;if(c.kind==PR_COMPLETION_RETIRED){require(c.resources_retired==1,"actual authored retirement fact");retired=true;}require(c.has_grant==static_cast<uint32_t>(sealed)&&c.has_scope==static_cast<uint32_t>(sealed),"completion preserves actual seal state");if(sealed)require(c.scope.policy.output_generation==1&&c.scope.objects[0].id==77&&c.native.kind==PR_NATIVE_RETURNED,"old sealed copied scope survives reconciliation");else require(c.native.kind==PR_NATIVE_NOT_ENTERED,"no native entry on revoked unsealed work");}require(outcome==1&&attempt==static_cast<unsigned>(sealed),"separate real attempt/outcome/retirement accounting");}
void old_unsealed(Mode mode){start(mode);initial_ready();const auto a=submit(mode==Mode::PREPARE_HELD?11:12);probe.wait(mode==Mode::PREPARE_HELD?PREPARE_ENTER:EXECUTE_ENTER,a.policy.scene_sequence);require(pr_executor_try_join(slot.owner)==PR_EXECUTOR_BUSY,"held unsealed callback retains worker");retained_release();require(pr_executor_invalidate_session_v2(slot.owner,SESSION)==PR_EXECUTOR_OK,"direct invalidation returns before old final attempt");/* No further Rust observer/control call intervenes before actual worker authorization. */if(mode==Mode::PREPARE_HELD)probe.open(&Probe::prepare_open);else probe.open(&Probe::execute_open);probe.wait(AUTHORIZE_REFUSED,a.policy.scene_sequence);const auto invalidated=state();require(invalidated.invalidation_epoch==1&&invalidated.admitted_epoch==0&&invalidated.accepted_epoch==0,"direct revocation retained before ingress");no_ready();refuse_dirty_frame();enqueue(4);probe.wait(APPLY_ENTER,4);probe.open_apply(0);caught_up(1,4);drain(a,false);size_t n=0;const auto records=probe.copy(n);unsigned authorized=0,refused=0;for(size_t i=0;i<n;++i){authorized+=records[i].event==AUTHORIZED;refused+=records[i].event==AUTHORIZE_REFUSED;}require(authorized==0&&refused==1,"one actual stale worker authorization no native entry");close_owner();}
