void late_candidate(){const auto original=now()+150000000ULL;start(Mode::ORDINARY,original);invalidate();enqueue(4);probe.open(&Probe::bootstrap_open);probe.wait(APPLY_ENTER,4);require(state().reconcile_not_after_boottime_ns==original,"held apply retains original startupdeadline");const auto cutoff=until();while(slot.wait(cutoff)!=2){}require(now()>=original,"actual original BOOTTIME timer readable");const auto expired=snapshot();require(expired.stopping&&expired.failed&&expired.worker_alive&&!expired.ready,"timer expiry retains held worker unready");require(pr_executor_try_join(slot.owner)==PR_EXECUTOR_BUSY,"expired held apply retains joinBusy");retained_release();probe.open_apply(0);probe.wait(APPLY_RETURN,4);probe.wait(SHUTDOWN_PENDING);auto d=sentinel<PrDiscoveryV1>();const auto db=bytes(d);require(pr_executor_discovery_v1(slot.owner,&d)==PR_EXECUTOR_EMPTY&&bytes(d)==db&&!snapshot().ready,"late successful callback never resurrectsReady");const auto terminal_state=state();require(terminal_state.reconcile_not_after_boottime_ns==original,"terminal copiedread remains available without reneweddeadline");close_owner();pass("real_original_startup_timer_late_apply_never_Ready");}
bool cleanup()noexcept{probe.all_open();if(slot.owner){pr_executor_stop(slot.owner);bool joined=false;for(;;){uint64_t t=0;try{t=now();}catch(...){return false;}if(t>=close_until)break;const auto c=pr_executor_try_join(slot.owner);if(c==PR_EXECUTOR_OK){joined=true;break;}if(c!=PR_EXECUTOR_BUSY)return false;std::this_thread::yield();}if(!joined)return false;try{slot.unwatch();}catch(...){return false;}if(pr_executor_try_release(&slot.owner)!=PR_EXECUTOR_OK||slot.owner)return false;}if(slot.epoll>=0){close(slot.epoll);slot.epoll=-1;}return true;}
