int main(){try{control_tid=tid();const auto start=now();work_until=start+5*SECOND;close_until=start+8*SECOND;std::printf("SESSION_RECONCILE_BOUNDS main_tid=%d started_ns=%llu work_until_ns=%llu close_until_ns=%llu\n",control_tid,static_cast<unsigned long long>(start),static_cast<unsigned long long>(work_until),static_cast<unsigned long long>(close_until));tests();require(cleanup(),"actual success custody closure");std::printf("SESSION_RECONCILE_ALL_PASS groups=6 completed_ns=%llu\n",static_cast<unsigned long long>(now()));return 0;}catch(const std::exception& e){std::fprintf(stderr,"SESSION_RECONCILE_FAIL %s\n",e.what());std::fflush(stderr);if(!cleanup()){std::fputs("SESSION_RECONCILE_RETAINED_WORKER_PROCESS_EXIT_NO_JOIN_CLAIM\n",stderr);std::fflush(stderr);std::_Exit(1);}return 1;}catch(...){std::fputs("SESSION_RECONCILE_FAIL exception\n",stderr);std::fflush(stderr);if(!cleanup())std::_Exit(1);return 1;}}
